quests[44156] = { id = 44156, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch weniger Arcan'dor als je zuvor...", description = "Ich hoffe, Euch ist jetzt klar, was auf dem Spiel steht.\n\nKommt. Für uns gibt es hier nichts mehr zu tun.\n\nWir treffen uns in Shal'Aran und beraten, wie es weitergeht.", sourceObjective = "Kehrt nach Shal'Aran zurück.", completion = "Wir müssen eine Lösung finden. Uns läuft die Zeit davon.", sourceObjectiveStatus = "unverified-source-field" }
quests[44157] = { id = 44157, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdorrte Streitereien: Tel'anor" }
quests[44158] = { id = 44158, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdorrte Streitereien: Falanaar" }
quests[44159] = { id = 44159, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Ticket für Marin", description = "Dieses Tresorticket sollte an Marin Noggenfogger geliefert werden.", sourceObjective = "Bringt Marin Noggenfogger das Tresorticket.", completion = "Seid nicht schüchtern, {name}. Entscheidet Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[44161] = { id = 44161, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was Gaardoun so braucht", description = "Schlachtenfürst Gaardoun hat angeboten, weitere zerschlagene Krieger für die Sache anzuwerben. Er benötigt vorher aber ein paar Dinge. Er erwähnte so etwas wie das richtige Werkzeug für die Aufgabe, oder sowas.\n\nEs wird Zeit, unsere frischgebackenen Champions auf die Probe zu stellen. Ich bin sicher, es wird eine aufreibende Mission.", sourceObjective = "Benutzt die Späherkarte und schließt die Mission \"Was Gaardoun so braucht\" ab.", completion = "Nun, immerhin werden wir hier ein paar neue Gesichter zu sehen bekommen. Soweit man das Gesicht eines Zerschlagenen als neu bezeichnen kann...\n\n<Kor'vas grinst.>", sourceObjectiveStatus = "unverified-source-field" }
quests[44164] = { id = 44164, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein brennender Pfad durch die Zeit", description = "Der gleißende Stern wirft sein Licht auf das Land und lässt die Erde verdorren und ganze Landschaften versengen. Es ist ein gnadenloser, fast schon bösartiger Stern. Unter seinem Einfluss eröffnen sich neue Wege – zu weit entfernten Orten und sogar zu weit entfernten Zeiten. Kein Weiser ist in der Lage, die Bedeutung dieses Zeichens vollständig zu verstehen, aber das Glück ist mit den Mutigen.", sourceObjective = "Schließt 5 Zeitwanderungsdungeons ab.", completion = "Ah, {name}. Ihr seid zurück. Euch umgibt wahrlich eine Aura aus einer anderen Welt.", sourceObjectiveStatus = "unverified-source-field" }
quests[44166] = { id = 44166, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein gefrorener Weg durch die Zeit", description = "Der kalte Stern wirft sein frostiges Licht auf das Land und selbst die Schatten ziehen sich zurück. Es ist ein Stern wie kein zweiter, der alle Wärme und Leben entzieht. Unter seinem Einfluss eröffnen sich neue Wege – zu weit entfernten Orten und sogar zu weit entfernten Zeiten. Kein Weiser ist in der Lage, die Bedeutung dieses Zeichens vollständig zu verstehen, aber das Glück ist mit den Mutigen.", sourceObjective = "Schließt 5 Zeitwanderungsdungeons ab.", completion = "Ah, {name}. Ihr seid zurück. Euch umgibt wahrlich eine Aura aus einer anderen Welt.", sourceObjectiveStatus = "unverified-source-field" }
quests[44167] = { id = 44167, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein verwüsteter Pfad durch die Zeit", description = "Der Stern des Zerstörers bedeckt das Land mit seinem durchdringenden Licht, sodass sich selbst die Geister in die Schatten zurückziehen. Dieser Stern ist wie kein anderer am Himmel. Er offenbart selbst die Schwächen der furchtlosesten Helden. Solange er am Himmel steht, können sich neue Pfade zu fernen Orten oder sogar Zeiten eröffnen. Die Gelehrten sind ratlos, was die Natur dieses Zeichens betrifft, doch das Glück belohnt bekanntlich die Mutigen.", sourceObjective = "Schließt 5 Zeitwanderungsdungeons ab.", completion = "Ah, {name}. Ihr seid zurück. Euch umgibt wahrlich eine Aura aus einer anderen Welt.", sourceObjectiveStatus = "unverified-source-field" }
quests[44171] = { id = 44171, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abgesandter des Krieges", description = "Wenn das Zeichen des Kriegers am Nachthimmel leuchtet, ist das Schicksal den Wagemutigen hold. Mächtige Feinde können noch größere Belohnungen erbringen. Begebt Euch tief in die Höhlen und Festungen, um Euch als würdig zu erweisen.", sourceObjective = "Schließt 4 Dungeons auf dem Schwierigkeitsgrad 'Mythisch' ab.", completion = "Gut gemacht, {name}. Ich wusste, dass Ihr es schaffen würdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[44172] = { id = 44172, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Arena ruft", description = "Diese Sternenkonstellation ist ein düsteres Omen. Sie ruft Blutlust hervor und zwingt Krieger zur Teilnahme an tödlichen Nahkämpfen. Die Arenameister verdienen gut dieser Tage. Vermutlich wissen sie nicht einmal, warum so viele Krieger in ihren Arenen antreten wollen. Neben der fiebrigen Spannung erwarten alle, die mutig oder töricht genug sind, sich diesen Arenakämpfen zu stellen, große Belohnungen...", sourceObjective = "Gewinnt 10 Arenageplänkel.", completion = "Gut gemacht, {name}. Ich wusste, Ihr würdet es vollbringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44173] = { id = 44173, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Aufruf zur Schlacht", description = "Das Sternbild des Kriegsherren beherrscht den Himmel und bringt allen Strategen Glück. Einige sagen, dieses Sternbild schärft die Instinkte von Kommandanten so weit, dass es Wahrsagerei gleicht. Wenn Ihr je daran gedacht habt, Euch auf dem Schlachtfeld zu beweisen, ist jetzt die richtige Zeit dafür.", sourceObjective = "Gewinnt 4 Schlachtfeldpartien.", completion = "Ich vermute, dass Eure Schlachten gut verlaufen sind. Eigentlich ist das keine Vermutung. Ich weiß es. Ich wusste es schon immer.", sourceObjectiveStatus = "unverified-source-field" }
quests[44174] = { id = 44174, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haustierchampion", description = "Dies ist eine wahrhaft ungewöhnliche Sternenkonstellation. Sie ist dafür verantwortlich, dass die kleinsten Kreaturen ungewöhnliche Fähigkeiten entwickeln. Keiner unserer Weisen kann dieses Phänomen erklären, aber für geschickte Zähmer ist dies eine perfekte Gelegenheit, ihre Fähigkeiten gegen andere auf die Probe zu stellen.", sourceObjective = "Besiegt 5 Spieler über 'Kampf finden' mit einer Gruppe aus Haustieren auf Stufe 25.", completion = "Gut gemacht, {name}. Ihr habt Mut bewiesen, alle Herausforderungen auf dem Wege bestanden, und Euch über Tage hinweg den Platz erkämpft, der Euch zusteht.", sourceObjectiveStatus = "unverified-source-field" }
quests[44175] = { id = 44175, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Welt wartet", description = "Wenn das Zeichen des Gesandten am Nachthimmel leuchtet, festigen die Sterne ihre bestehenden Bande und knüpfen neue. Freundschaft wird nicht leichtfertig vergeben und nur durch Taten wird Treue bewiesen, aber Vertrauen stellt sich in diesen Tagen schneller ein. Bereist die Verheerten Inseln und helft, wo Ihr könnt, um Euch als würdig zu erweisen.", sourceObjective = "Schließt 20 Weltquests auf den Verheerten Inseln ab.", completion = "Gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[44176] = { id = 44176, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Annehmlichkeiten eines Zuhauses", description = "Diese Truhe könnte uns gute Dienste leisten. Bringt sie nach Shal'Aran.", sourceObjective = "Bringt die Banktruhe des Reisenden nach Shal'Aran.", completion = "Diese schwere Kiste bietet genug Platz für all Euren Besitz.", sourceObjectiveStatus = "unverified-source-field" }
quests[44177] = { id = 44177, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkle Geheimnisse und krumme Geschäfte", description = "Was auch immer Amber Kearnen gewusst hat, Mathias Shaw wollte nicht, dass jemand davon erfährt...\n\nWirklich ein dreckiges Geschäft, den Roten Säbel zu so 'nem Preis anzuheuern, bloß um jemanden aus der eigenen Mannschaft zu töten!\n\nIhr macht Euch besser auf den Weg zurück zur Halle der Schatten und erzählt Lord Rabenholdt, was wir hier in der Citrinbucht rausgefunden haben.\n\nWas auch immer der SI:7 plant, dahinter steckt mehr, als wir vermutet hatten...", sourceObjective = "Sprecht mit Lord Rabenholdt.", completion = "Der SI:7 hat insgeheim den Roten Säbel angeheuert, um Amber Kearnen zur Strecke zu bringen?\n\nMeister Mathias Shaw wollte sie wohl um jeden Preis loswerden...", sourceObjectiveStatus = "unverified-source-field" }
quests[44178] = { id = 44178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein besonders mächtiger Trank", description = "Ich habe einen Vorschlag für Euch, {name}!\n\nEs heißt, Handelsprinz Gallywix hätte vor Kurzem einen unbezahlbaren und einzigartigen Liebestrank erworben. Es gibt nur einen Goblin, der so etwas nachbrauen könnte... mich! Besorgt mir diesen Trank und ich mache uns zwei so reich, dass alle Könige grün vor Neid werden!\n\nDas Lustschloss befindet sich in Azshara und wird seit Ausbruch des Krieges streng bewacht. Gallywix lässt nur sein eigenes Personal hinein, aber ich kenne eins der Mädchen, die dort arbeiten!\n\nFindet sie und sie führt Euch zum Tresor!", sourceObjective = "Stehlt Liebestrank Nr. 6 aus dem persönlichen Tresor von Gallywix.", progress = "Habt Ihr die Ware?", completion = "Aah, klasse! Das ist es!\n\n<Noggenfogger entkorkt die Flasche und träufelt etwas auf seinen Finger.>\n\nAber HALLO! Puuh... Ich glaube, ich brauche etwas Zeit allein mit dem Zeug!", sourceObjectiveStatus = "unverified-source-field" }
quests[44179] = { id = 44179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure" }
quests[44180] = { id = 44180, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Marin Noggenfogger", sourceObjective = "Ich will ehrlich mit Euch sein, {name}...\n\nOhne Eure Diebeskünste wäre ich heute wesentlich ärmer, als ich es bin. Ich denke, wir sollten diese wortwörtlich goldene Partnerschaft nicht so schnell beenden!\n\nEine Hand wäscht die andere. Zusammen werden wir die Brennende Legion aufhalten und unsere Taschen mit den Schätzen von ganz Azeroth füllen!", sourceObjectiveStatus = "unverified-source-field" }
quests[44181] = { id = 44181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Flottenadmiral Tethys", sourceObjective = "Ha, mien Jung! Wir haben wirklich einiges erlebt! Jede Menge Blut vergossen, jede Menge Rum getrunken und alle möglichen Geheimnisse gelüftet!\n\nJetzt mal unter uns, {name}. Solche Abenteuer hab ich schon seit Jahren nicht mehr erlebt. Mit Euch zu segeln, ist wie eisige Gischt nach einer durchzechten Nacht. Man fühlt sich so richtig lebendig!\n\nNehmt Ihr mich als Bootsmann mit an Bord?", sourceObjectiveStatus = "unverified-source-field" }
quests[44182] = { id = 44182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stadt unter Belagerung", description = "<Khadgars Stimme ertönt erneut aus dem Elementar.>\n\nEs war ein bedeutender Sieg, dass Ihr die Informationen über die Säulen der Schöpfung erlangen konntet, bevor die Legion uns aufhalten konnte. Es wird zwar jene, die an der Verheerten Küste gefallen sind, nicht zurückbringen, aber es wird helfen, sie zu rächen.\n\nDie Angriffe der Legion konzentrieren sich jetzt auf Dalaran. Wir brauchen Euch hier nun dringender als je zuvor. Wenn die Dämonen so versessen darauf sind, Dalaran zu erobern, bedeutet dies, dass die Stadt im Kampf um Azeroth eine entscheidende Rolle spielt.", sourceObjective = "Trefft Khadgar an der Kammer des Wächters in Dalaran.", completion = "Ich habe die Verteidigung von Karazhan zwar so gut ich konnte verstärkt, aber ich bezweifle trotzdem, dass sie halten wird. Und es gibt noch andere Dinge, um die wir uns kümmern müssen.\n\nGul'dan hat seine Höllenhunde auf Dalaran losgelassen. Er will diese Stadt auslöschen... aber das werden wir nicht zulassen.\n\nIch glaube, dass Dalaran in unserem Kampf gegen die Legion eine entscheidende Rolle einnehmen wird... als neutraler Boden, auf dem die Helden aller Königreiche sich gegen den gemeinsam Feind zusammenschließen können.\n\nMachen wir uns also an die Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[44183] = { id = 44183, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Lord Jorach Rabenholdt", sourceObjective = "Wir sind da auf ein gefährliches Rätsel gestoßen, {name}. Es wäre nicht recht, wenn ich nur tatenlos zuschaue, während Ihr Euer Leben riskiert, um dieser Verderbnis auf den Grund zu gehen.\n\nImmerhin würde ohne Ehre und Verbundenheit unter den Dieben keiner von uns je etwas verdienen!\n\nVon jetzt an stelle ich all mein Können in den Dienst Eurer Sache. Lasst uns die Brennende Legion aufhalten und dieses dunkle Geheimnis lüften, {name}...", sourceObjectiveStatus = "unverified-source-field" }
quests[44184] = { id = 44184, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In einem flüchtigen Augenblick", description = "Unser Ziel sind die Verheerten Inseln, {name}.\n\nDer Zauber, der Dalaran innerhalb eines Lidschlags an seinen neuen Standort versetzt, ist nicht einfach. Ich brauche die volle Energie und Aufmerksamkeit dieses Rats.\n\nDa Jaina... abwesend ist, hat Kalecgos vom blauen Drachenschwarm uns seine Hilfe angeboten.\n\nDie Legion wird alles versuchen, um uns aufzuhalten, aber wir werden nicht klein beigeben. Es ist Zeit, anzufangen!", sourceObjective = "Werdet Zeuge, wie Dalaran zu den Verheerten Inseln teleportiert wird.", completion = "Ah, {name}, schön, Euch wieder auf den Beinen zu sehen! Die Mitglieder des Rats der Sechs erholen sich von den Strapazen.\n\nDie Intensität des Teleportationszaubers kann dem Geist stark zusetzen. Anscheinend habt Ihr kurz das Bewusstsein verloren, aber immerhin seid Ihr nicht in einer Wand aufgewacht!\n\nDalaran wurde über die Verheerten Inseln versetzt. Von hier aus werden wir die Suche nach den Säulen der Schöpfung leiten und die Legion endgültig aus Azeroth vertreiben!", sourceObjectiveStatus = "unverified-source-field" }
quests[44185] = { id = 44185, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Sanaar" }
quests[44186] = { id = 44186, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GESUCHT: Brutmutter Shu'malis" }
quests[44187] = { id = 44187, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "GEFAHR: Glutschwinge" }
quests[44188] = { id = 44188, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Special Army of the Dead Summoned" }
