quests[44195] = { id = 44195, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arbeitsaufträge für Waffen", description = "Ich kann Euch die besten Konditionen für... leicht gebrauchte... Ausrüstung bieten.", sourceObjective = "Erteilt einen Arbeitsauftrag für eine Lieferung Waffen und Ausrüstung für Champions.", completion = "Die Aufträge sind erteilt, meine Leute kümmern sich um alles. Kommt in Kürze wieder, dann könnt Ihr Eure Lieferung direkt mitnehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44196] = { id = 44196, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mathias' Besuch nicht aktiv 01" }
