quests[44201] = { id = 44201, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mathias' Besuch nicht aktiv 06" }
quests[44202] = { id = 44202, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die gemeinsame Sache", sourceObjective = "Ich hoffe, es stört Euch nicht, dass ich so unerwartet vorbeischaue, {name}. Ich hatte gerade ein paar Geschäfte in dieser Gegend zu erledigen.\n\nMeine Leute haben einige wirklich nette Waffen gefunden, die Euch Eurem Ziel etwas näherbringen könnten. Ich bin sicher, Ihr wisst am besten, wie sie zu verteilen sind.\n\nAuch wenn unsere Zusammenarbeit nicht gerade an die große Glocke gehängt werden sollte, könnt Ihr Euch einer Sache sicher sein: Sie wird im Krieg gegen die Brennende Legion eine entscheidende Rolle spielen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44203] = { id = 44203, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die gemeinsame Sache", sourceObjective = "Schattenklinge {name}, immer eine Freude. Ich war gerade für die Allianz hier in der Gegend und dachte, ich sehe mal vorbei. Die Dinge scheinen für uns ganz gut zu laufen.\n\nMeine Leute haben einige wirklich hübsche Waffen gefunden, die Euch Eurem Ziel etwas näherbringen könnten. Ich bin sicher, Ihr wisst am besten, wie sie zu verteilen sind.\n\nAuch wenn wir hinter geschlossenen Türen zusammenarbeiten und im Verborgenen agieren, könnt Ihr Euch auf eines fest verlassen: Der SI:7 und ich werden Euch für die gesamte Dauer des Krieges gegen die Brennende Legion unterstützen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44204] = { id = 44204, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besiegelt ihr Schicksal", description = "Hattet Ihr auch schon einmal das Gefühl, das Glück wäre Euch nicht gerade hold? Nun, da kann ich Euch vielleicht helfen.\n\nIch habe auf meinen Reisen einige interessante Dinge gefunden, mit denen Ihr das Glück in Eure Richtung lenken könnt... oder zumindest eine zweite Chance bekommt. Diese Dinger wachsen nicht gerade auf Bäumen und es wird etwas Zeit in Anspruch nehmen, aber ich könnte Euch ein Exemplar sichern... für einen gewissen Preis.", sourceObjective = "Erteilt einen Arbeitsauftrag für ein Siegel des verheerten Schicksals.", completion = "Der Auftrag wurde verschickt. Sobald meine Leute den Gegenstand gefunden haben, wird er hier für Euch hinterlegt.\n\nViel... Glück.", sourceObjectiveStatus = "unverified-source-field" }
quests[44205] = { id = 44205, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schmiedet Euer Schicksal", description = "Der Wille der Geister lässt sich lenken. Ich habe es gesehen.\n\nEs gibt Gerüchte über einen Gegenstand, der den Lauf des Schicksals verändern kann. Also habe ich zugehört und mich auf die Suche gemacht. Viele Jahre folgte ich dem Flüstern des Windes, und eines Tages fand ich den Weg. Dieses Wissen kann ich Euch anbieten. Es wird einige Zeit dauern und einige wertvolle Ressourcen beanspruchen, aber ich kann das Ritual für Euch durchführen, auf dass diese Macht Euch gehöre.\n\nUnd? Seid Ihr bereit?", sourceObjective = "Erteilt einen Arbeitsauftrag für ein Siegel des verheerten Schicksals.", completion = "Das Ritual hat begonnen und wird einige Zeit beanspruchen. Kommt später wieder.", sourceObjectiveStatus = "unverified-source-field" }
quests[44206] = { id = 44206, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Aufgestiegenen", description = "Diese Schamanen haben ihr Leben dem Weg der Luft, des Wassers oder des Feuers gewidmet. Auf Euer Geheiß werden wir die Elemente bitten, sie als Aufgestiegene zu erwählen. Damit werden sie, wenn auch nur für kurze Zeit, zu einer unglaublich starken Waffe im Krieg gegen die Legion.\n\nAber bedenkt: Das Ritual des Aufstiegs sollte man nicht leichtfertig erbitten.", sourceObjective = "Stellt ein Rekrutierungsgesuch für Aszendenten.", completion = "Das Ritual hat begonnen, sie werden aufsteigen. Kehrt zurück, wenn das Ritual abgeschlossen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[44207] = { id = 44207, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Portal voller Glitzerkram", description = "Als ich hörte, die Halle des Wächters sei wieder eröffnet, sagte ich zu mir: \"Minuette, das ist DIE Chance!\" Ich rannte den ganzen Weg hierher mit nur einem Gedanken: \"Bald stehe ich an vorderster Front, weiche Teufelsmeteoren aus und erledige ganze Heere von Dämonen mit meinen Geschossen.\" Das wäre ein Spaß geworden.\n\nStattdessen haben sie mich hierhergeschickt und gesagt: \"He, öffnet mal ein paar Portale, damit wir alles Mögliche hindurchwerfen können. Alles klar?\". Na ja, zumindest muss ich nicht umsonst arbeiten.", sourceObjective = "Erteilt einen Arbeitsauftrag für Championwaffen und -ausrüstung.", completion = "All die jahrelangen Studien machen sich endlich bezahlt...\n\nSobald sie die Lieferung durchgeschickt haben, wird sie hier für Euch gelagert.", sourceObjectiveStatus = "unverified-source-field" }
quests[44208] = { id = 44208, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schicksal und Zeit", description = "Jahre haben wir uns gefragt: Ist es möglich, die Fäden des Schicksals zu lenken, obwohl sie ständig in Bewegung sind? Diese Bücher erzählen von mächtigen Magiern, die sogar die Zeit selbst manipulieren konnten. Nein, nein, nicht wie 'Zeitkrümmung'. Sie würden uns dafür auslachen und als Amateure abtun. Nein, das waren echte Chronomanten.\n\nDer einzige Zauber, den wir identifizieren konnten, ist eine Beschwörung. Mit ihr ruft man etwas herbei, das sie \"Schicksalssiegel\" nannten. Damit konnten sie ihre Taten wiederholen. Wollen wir es ausprobieren?", sourceObjective = "Erteilt einen Arbeitsauftrag für ein Siegel des verheerten Schicksals.", completion = "Der Zauber hat begonnen. Kehrt zu mir zurück, wenn er abgeschlossen ist. Das Schicksal liegt nun in den Händen der Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[44209] = { id = 44209, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht von Dalaran", description = "In Zeiten größter Not können die Magier von Dalaran ihre Macht zu einer reinen und sehr zerstörerischen Form bündeln. Dies ist solch eine Zeit.\n\nAuf Euer Wort werden die Magier ihre Macht in einen Fokussierkristall kanalisieren, den wir Euch dann übergeben. Wenn Ihr seine Macht entfesselt, könnt Ihr eine wichtige Aufgabe abschließen.", progress = "Kanalisiert die Macht von Dalaran in den Fokussierkristall und entfesselt sie dann, um eine Weltquest abzuschließen.", completion = "Gut gemacht, aber das war eine unglaubliche Anstrengung für uns alle. Es wird etwas dauern, bevor wir diese Aufgabe erneut in Angriff nehmen können." }
quests[44211] = { id = 44211, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsichtbare Waffen", description = "Wenn wir diesen Krieg gewinnen wollen, brauchen wir bessere Ausrüstung für Eure Champions.\n\nDas wird schwierig und teuer, aber ich krieg das hin.", sourceObjective = "Erteilt einen Arbeitsauftrag für Championwaffen und -ausrüstung.", completion = "Der Auftrag ist erteilt. Sobald die Lieferung eingetroffen ist, wird sie hier für Euch gelagert.", sourceObjectiveStatus = "unverified-source-field" }
quests[44212] = { id = 44212, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsichtbares Schicksal", description = "Unser Pfad ist steinig, verschlungen und voller Gefahren. Aber habt Ihr gewusst, dass man ihn mehrmals beschreiten kann? Uns steht ein Gegenstand von unglaublicher Macht zur Verfügung. Er gewährt uns eine weitere Gelegenheit... eine zweite Chance.\n\nSeid Ihr an einem solchen Gegenstand interessiert?", sourceObjective = "Erteilt einen Arbeitsauftrag für ein Siegel des verheerten Schicksals.", completion = "Die Befehle sind erteilt. Das Siegel wird in Kürze eintreffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44213] = { id = 44213, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr wisst, was Euch erwartet!", description = "{name}, Eure Kraft und Führungsqualitäten sind eine Inspiration für uns alle!\n\nDie Illidari möchten Euch eine komplette Rüstung für den Kampf gegen die Brennende Legion zur Verfügung stellen. Erweitert Euren Einfluss auf den Rest der Verheerten Inseln, dann ist der Sieg eines Tages unser.", sourceObjective = "Nehmt ein Geschenk von den Illidari an.", completion = "Unsere Gleven gehören Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[44214] = { id = 44214, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch eine Sache...", description = "Gut gemacht, <Rächer/Rächerin>. Nun seid Ihr wahrhaftig <der Anführer/die Anführerin> der Illidari. Aber da wäre noch eine Sache.\n\nTreffen wir uns an der Schmiede.", sourceObjective = "Begebt Euch zur Kammer der verfluchten Schmiede der Nathrezim auf dem unteren Deck der Teufelshammer.", completion = "Ausgezeichnet. Das wird Euch gefallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44215] = { id = 44215, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch eine Sache...", description = "Erlaubt mir zunächst, Euch zu beglückwünschen. Ich kann mir niemanden vorstellen, der den Titel Schattenklinge mehr verdient als Ihr. Aber da wäre noch eine Sache.\n\nTreffen wir uns an der Schmiede.", sourceObjective = "Trefft Euch mit Lord Rabenholdt in der Schatzkammer der Ungekrönten.", completion = "Ich denke, das wird Euch gefallen. Ich gebe zu, ich bin sogar etwas neidisch.", sourceObjectiveStatus = "unverified-source-field" }
quests[44217] = { id = 44217, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rüstung eines wahren Todesgebieters", description = "{name} ist stark! {name} ist <großer Anführer/große Anführerin>!\n\nSchwarze Klinge gibt Euch eine Rüstung. Gut für Euch, schlecht für Dämonen. Werdet stärker, tötet noch mehr Dämonen!", sourceObjective = "Nehmt ein Geschenk von den Rittern der Schwarzen Klinge an.", completion = "Wir stehen zu Euch, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[44218] = { id = 44218, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen für Champions", description = "Diesen Krieg gegen die Legion zu gewinnen, wird nicht einfach. Wir brauchen Waffen und Ausrüstung für unsere Champions.\n\nGebt den Befehl, und ich sorge für eine neue Lieferung.", sourceObjective = "Erteilt einen Arbeitsauftrag für Championwaffen und -ausrüstung.", completion = "Zu Befehl, die Männer wissen Bescheid. Sobald die Lieferung eingetroffen ist, wird sie hier für Euch gelagert.", sourceObjectiveStatus = "unverified-source-field" }
quests[44219] = { id = 44219, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Segen des Schicksals", description = "Der Segen des Lichts ist mächtig. Er erlaubt uns, Wunden zu heilen, unsere Feinde zu bezwingen und sogar gefallene Verbündete von den Toten zurückzuholen. Habt Ihr gewusst, dass sich damit auch Euer Schicksal verändern lässt?\n\nDie Silberne Hand kann ein wertvolles Siegel beschaffen, das Euch im Krieg gegen die Legion gute Dienste leisten wird. Wenn Ihr dieses Siegel im rechten Moment einsetzt, erhaltet Ihr eine zweite Chance, Euer Schicksal zu erfüllen.\n\nSollen wir das Siegel für Euch beschaffen?", sourceObjective = "Erteilt einen Arbeitsauftrag für ein Siegel des verheerten Schicksals.", completion = "Die Befehle sind erteilt. Das Siegel wird in Kürze eintreffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44220] = { id = 44220, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Segen des Ordens", description = "In Zeiten größter Not kann der Orden seine Stärke zu einer reinen und sehr zerstörerischen Form vereinen. Dies ist solch eine Zeit.\n\nAuf Euer Wort werden wir unsere Kraft in einen Buchband kanalisieren, den wir Euch dann übergeben. Wenn Ihr seine Macht entfesselt, könnt Ihr eine wichtige Aufgabe abschließen.", sourceObjective = "Lasst die Vorhut zusammenrufen und entfesselt ihre Macht, um eine Weltquest abzuschließen.", completion = "Gut gemacht, aber das war eine unglaubliche Anstrengung für uns alle.", sourceObjectiveStatus = "unverified-source-field" }
quests[44221] = { id = 44221, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen für Champions", description = "Ein Krieger lebt und stirbt mit seinen Waffen und seiner Rüstung. Zum richtigen Preis können wir Euch mit einer Lieferung Waffen für Eure Champions versorgen.\n\nSeid Ihr einverstanden?", sourceObjective = "Erteilt einen Arbeitsauftrag für Championwaffen und -ausrüstung.", completion = "Der Auftrag ist erteilt. Sobald die Lieferung eingetroffen ist, wird sie hier für Euch gelagert.", sourceObjectiveStatus = "unverified-source-field" }
quests[44222] = { id = 44222, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Macht der Val'kyr", description = "In Zeiten größter Not können die Val'kyr ihre Stärke zu einer reinen und sehr zerstörerischen Form vereinen. Dies ist solch eine Zeit.\n\nAuf Euer Wort werden wir unsere Kraft in ein Horn kanalisieren, das wir Euch dann übergeben. Wenn Ihr seine Macht entfesselt, könnt Ihr eine wichtige Aufgabe abschließen.", sourceObjective = "Bündelt die Stärke der Val'kyr und entfesselt sie dann, um eine Weltquest abzuschließen.", completion = "Gut gemacht, aber das war eine unglaubliche Anstrengung für uns alle.", sourceObjectiveStatus = "unverified-source-field" }
quests[44223] = { id = 44223, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen für Champions", description = "Wir brauchen Waffen und Ausrüstung für unsere Champions.", sourceObjective = "Erteilt einen Arbeitsauftrag für Championwaffen und -ausrüstung.", completion = "Der Auftrag ist erteilt. Sobald die Lieferung eingetroffen ist, wird sie hier für Euch gelagert.", sourceObjectiveStatus = "unverified-source-field" }
quests[44224] = { id = 44224, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unser entfesselter Zorn", description = "In Zeiten größter Not können wir unsere Stärke zu einer reinen und sehr zerstörerischen Form vereinen. Dies ist solch eine Zeit.\n\nAuf Euer Wort werden wir unsere Kraft in einen Gegenstand kanalisieren, den wir Euch dann übergeben. Wenn Ihr seine Macht entfesselt, könnt Ihr eine wichtige Aufgabe abschließen.", sourceObjective = "Kanalisiert die Macht des Hammers und entfesselt sie dann, um eine Weltquest abzuschließen.", completion = "Gut gemacht, aber das war eine unglaubliche Anstrengung für uns alle.", sourceObjectiveStatus = "unverified-source-field" }
quests[44226] = { id = 44226, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal ist uns wohlgesonnen", description = "Wir können ein wertvolles Siegel beschaffen, das Euch im Krieg gegen die Legion gute Dienste leisten wird. Wenn Ihr dieses Siegel im rechten Moment einsetzt, erhaltet Ihr eine zweite Chance, Euer Schicksal zu erfüllen.\n\nSollen wir das Siegel für Euch beschaffen?", sourceObjective = "Erteilt einen Arbeitsauftrag für ein Siegel des verheerten Schicksals.", completion = "Die Befehle sind erteilt. Das Siegel wird in Kürze eintreffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44227] = { id = 44227, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unser entfesselter Zorn", description = "In Zeiten größter Not können wir unsere Stärke zu einer reinen und sehr zerstörerischen Form vereinen. Dies ist solch eine Zeit.\n\nAuf Euer Wort werden wir mit einem Ritual beginnen, das eine mächtige Höllenbestie versklavt und in ein dämonisches Phylakterium bannt. Dieses Phylakterium übergeben wir dann an Euch. Wenn Ihr seine Macht entfesselt, könnt Ihr eine wichtige Aufgabe abschließen.", sourceObjective = "Beginnt mit dem Ritual zur Versklavung der Höllenbestie und entfesselt sie dann, um eine Weltquest abzuschließen.", completion = "Gut gemacht, aber das war eine unglaubliche Anstrengung für uns alle.", sourceObjectiveStatus = "unverified-source-field" }
quests[44228] = { id = 44228, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen für Champions", description = "Seht Ihr Lurr? Groß und stark, aber nicht sehr schlau. Nicht so wie Murr. Murr kann Lurr sagen, er soll tolle Sachen für Euch bauen. Sachen für Eure Champions zum Draufhauen.\n\nAber zuerst habt Ihr etwas für Murr?", sourceObjective = "Erteilt einen Arbeitsauftrag für Championwaffen und -ausrüstung.", completion = "Murr macht, dass Lurr nicht trödelt! Wenn fertig, alles kommt in eine Kiste. Kiste wartet dann hier auf Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[44229] = { id = 44229, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen für Champions", description = "Wir brauchen Waffen und Ausrüstung für unsere Champions.", sourceObjective = "Erteilt einen Arbeitsauftrag für Championwaffen und -ausrüstung.", completion = "Der Auftrag ist erteilt. Sobald die Lieferung eingetroffen ist, wird sie hier für Euch gelagert.", sourceObjectiveStatus = "unverified-source-field" }
quests[44230] = { id = 44230, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Möge uns das Schicksal segnen", description = "Wir können ein wertvolles Siegel beschaffen, das Euch im Krieg gegen die Legion gute Dienste leisten wird. Wenn Ihr dieses Siegel im rechten Moment einsetzt, erhaltet Ihr eine zweite Chance, Euer Schicksal zu erfüllen.\n\nSollen wir das Siegel für Euch beschaffen?", sourceObjective = "Erteilt einen Arbeitsauftrag für ein Siegel des verheerten Schicksals.", completion = "Die Befehle sind erteilt. Das Siegel wird in Kürze eintreffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44231] = { id = 44231, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen für Champions", description = "Die meisten Leute gucken eine Leiche an und denken: \"Was für ein stinkender Haufen.\" Ich bin da ganz anders. Ich sehe ein wunderschönes Geschenk mit vielen wundervollen Geheimnissen.\n\nUnd zum richtigen Preis teile ich diese Geheimnisse mit Euch.", sourceObjective = "Erteilt einen Arbeitsauftrag für Championwaffen und -ausrüstung.", completion = "Der Auftrag ist erteilt. Sobald die Lieferung eingetroffen ist, wird sie hier für Euch gelagert.", sourceObjectiveStatus = "unverified-source-field" }
quests[44232] = { id = 44232, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hain gibt", description = "{name}, Eure Weisheit und Führungsqualitäten sind eine Inspiration für uns alle!\n\nDie Traumweber möchten Euch eine komplette Rüstung für den Kampf gegen die Brennende Legion zur Verfügung stellen. Erweitert Euren Einfluss auf den Rest der Verheerten Inseln, dann ist der Sieg eines Tages unser.", sourceObjective = "Nehmt ein Geschenk von den Traumwebern an.", completion = "Wir stehen an Eurer Seite, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[44233] = { id = 44233, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dies ist Euer Pfad", description = "{name}, Eure Kraft und Führungsqualitäten sind eine Inspiration für uns alle!\n\nDer Unsichtbare Pfad möchte Euch eine komplette Rüstung für den Kampf gegen die Brennende Legion zur Verfügung stellen. Erweitert Euren Einfluss auf den Rest der Verheerten Inseln, dann ist der Sieg eines Tages unser.", sourceObjective = "Nehmt ein Geschenk vom Unsichtbaren Pfad an.", completion = "Wir folgen Euch auf Eurem Pfad, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[44234] = { id = 44234, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unser entfesselter Zorn", description = "In Zeiten größter Not können wir unsere Stärke zu einer reinen und sehr zerstörerischen Form vereinen. Dies ist solch eine Zeit.\n\nAuf Euer Wort werden wir unsere Kraft in einen Gegenstand kanalisieren, den wir Euch dann übergeben. Wenn Ihr seine Macht entfesselt, könnt Ihr eine wichtige Aufgabe abschließen.", sourceObjective = "Kanalisiert die Macht des Frostwyrms und entfesselt sie dann, um eine Weltquest abzuschließen.", completion = "Gut gemacht, aber das war eine unglaubliche Anstrengung für uns alle.", sourceObjectiveStatus = "unverified-source-field" }
quests[44235] = { id = 44235, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essenz des Schicksals", description = "Wir können ein wertvolles Siegel beschaffen, das Euch im Krieg gegen die Legion gute Dienste leisten wird. Wenn Ihr dieses Siegel im rechten Moment einsetzt, erhaltet Ihr eine zweite Chance, Euer Schicksal zu erfüllen.\n\nSollen wir das Siegel für Euch beschaffen?", sourceObjective = "Erteilt einen Arbeitsauftrag für ein Siegel des verheerten Schicksals.", completion = "Die Befehle sind erteilt. Das Siegel wird in Kürze eintreffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44236] = { id = 44236, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Essenz des Schicksals", description = "Wir können ein wertvolles Siegel beschaffen, das Euch im Krieg gegen die Legion gute Dienste leisten wird. Wenn Ihr dieses Siegel im rechten Moment einsetzt, erhaltet Ihr eine zweite Chance, Euer Schicksal zu erfüllen.\n\nSollen wir das Siegel für Euch beschaffen?", sourceObjective = "Erteilt einen Arbeitsauftrag für ein Schicksalssiegel.", sourceObjectiveStatus = "unverified-source-field" }
quests[44237] = { id = 44237, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urtume des Krieges", description = "Der Setzling ist eindeutig aufgeregt und verlangt nach Eurer Aufmerksamkeit. Vielleicht solltet Ihr ihm helfen?", progress = "Beginnt mit der Rekrutierung eines Urtums des Krieges.", completion = "Der Setzling ignoriert Euch, scheint allerdings schwer beschäftigt zu sein. Vielleicht solltet Ihr später zurückkehren." }
quests[44238] = { id = 44238, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meditationen über das Schicksal", description = "Wir können ein wertvolles Siegel beschaffen, das Euch im Krieg gegen die Legion gute Dienste leisten wird. Wenn Ihr dieses Siegel im rechten Moment einsetzt, erhaltet Ihr eine zweite Chance, Euer Schicksal zu erfüllen.\n\nSollen wir das Siegel für Euch beschaffen?", sourceObjective = "Erteilt einen Arbeitsauftrag für ein Siegel des verheerten Schicksals.", completion = "Die Befehle sind erteilt. Das Siegel wird in Kürze eintreffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44239] = { id = 44239, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echo eines Erhabenen", description = "Tianili ist eindeutig aufgeregt und verlangt nach Eurer Aufmerksamkeit. Vielleicht solltet Ihr ihm helfen?", sourceObjective = "Beginnt mit der Rekrutierung des Echos eines Erhabenen.", completion = "Tianili wirkt abgelenkt. Vielleicht solltet Ihr später zurückkehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[44240] = { id = 44240, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orange ist das neue Violett", description = "{name}, Eure Intelligenz und Führungsqualitäten sind eine Inspiration für uns alle!\n\nDie Tirisgarde möchte Euch eine komplette Rüstung für den Kampf gegen die Brennende Legion zur Verfügung stellen. Erweitert Euren Einfluss auf den Rest der Verheerten Inseln, dann ist der Sieg eines Tages unser.", sourceObjective = "Nehmt ein Geschenk von den Magiern der Tirisgarde an.", completion = "Unsere Herzen und unser Geist sind bei Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[44241] = { id = 44241, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Thassarian", sourceObjective = "Ihr erlernt:", sourceObjectiveStatus = "unverified-source-field" }
quests[44242] = { id = 44242, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Nazgrim", sourceObjective = "Ihr erlernt:", sourceObjectiveStatus = "unverified-source-field" }
quests[44243] = { id = 44243, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Thoras Trollbann", sourceObjective = "Die Ritter der Schwarzen Klinge sind ein mächtiger Orden, Todesgebieter.\n\nDer Respekt, den Ihr unter ihnen genießt, spricht für Eure Stärke und Führungsqualitäten.\n\nMein ganzes Leben lang habe ich zum Schutz meines Königreichs und meines Volkes gekämpft. Doch da ich als Vater versagte, klebt ihr Blut nun an meinen Händen.\n\nDeshalb werde ich das Versagen mit Dämonenblut von meinen Händen waschen. Der Zeitpunkt ist gekommen, mich wieder ins Kampfgetümmel zu stürzen. Mein Schwert steht unter Eurem Befehl.", sourceObjectiveStatus = "unverified-source-field" }
quests[44244] = { id = 44244, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Koltira Todesweber", sourceObjective = "Worte können nicht ausdrücken, wie dankbar ich Euch für meine Rettung bin, {name}. Ich wusste aber schon immer, dass mich die Schwarze Klinge nicht vergessen würde.\n\nLasst uns nicht länger von meiner jahrelangen Gefangenschaft sprechen. Diese Zeit ist vorüber, und nun müssen wir uns der drohenden Gefahr durch die Brennende Legion zuwenden.\n\nMeine Klinge gehört Euch, Todesgebieter. Verfügt über mein Leben und meine Treue, wie es Euch beliebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[44245] = { id = 44245, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Hochinquisitorin Weißsträhne", sourceObjective = "Kein Hass und keine Verachtung in dieser Welt könnten größer sein als die in meinem Herzen.\n\nDie Brennende Legion wird für all das bezahlen, was sie mir weggenommen hat.\n\nDer Tag meines Urteils wird kommen, aber ihrer steht unmittelbar bevor und ich werde die Klinge des Scharfrichters sein. Ich werde nicht eher ruhen, bis auch der letzte Dämon tot ist und ihre Kadaver den Weg pflastern, über den ich schreite!\n\nSchickt mich an die Front, Todesgebieter, und ich werde das blanke Entsetzen über die Armeen der Brennenden Legion bringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[44246] = { id = 44246, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Moderdarm", sourceObjective = "<Moderdarm gestikuliert in Eure Richtung, wobei er gurgelnd und rülpsend Worte aus seinem klaffenden Mund ausstößt.>\n\nModerdarm!!\n\nMODER. DARM. MODER! ModerdarmModerdarmModerdarm!!!\n\nDARM? Moderdarm, DARM. MODER... DARM!\n\nModerdarm??", sourceObjectiveStatus = "unverified-source-field" }
quests[44247] = { id = 44247, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Amal'thazad", sourceObjective = "Todesgebieter, ich bin nun seit einigen Jahren Euer bescheidener Lehrer in den dunklen Künsten. Von Eurer Geburt durch die Hand des Lichkönigs bis zu Eurer Ernennung als Anführer unseres Ordens habe ich mit großem Stolz beobachtet, wie Ihr an Macht gewonnen und den Untod gemeistert habt.\n\nIch glaube, die Zeiten, in denen ich Euch als Lehrer dienen konnte, sind vorüber. Vielleicht könnte ich Euch auf dem Schlachtfeld eher von Nutzen sein?\n\nEs ist Zeit, dass ich meine gefrorenen Knochen im Blut meiner Feinde erwärme. Bitte erlaubt mir, auf dem Schlachtfeld zu dienen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44248] = { id = 44248, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion: Darion Mograine", sourceObjective = "Die Vier Reiter der Schwarzen Klinge haben sich zusammengefunden, aber unsere Arbeit hat gerade erst begonnen.\n\nDie Brennende Legion ist hungrig nach Zerstörung in diese Welt eingefallen, doch wir werden ihren Hunger mit ihrem eigenen Niedergang stillen. Die Apokalypse erwartet die Dämoneneindringlinge und wir werden sie zu ihnen tragen!\n\nTodesgebieter, Ihr habt Triumphe gefeiert, wo niemand anders erfolgreich gewesen wäre. Ich werde die Vier Reiter anführen, wie es einst mein Vater getan hat, und solange ich sie anführe, werden sie Euch treu ergeben sein!\n\nDie Rückkehr der Vier Reiter steht bevor!", sourceObjectiveStatus = "unverified-source-field" }
quests[44249] = { id = 44249, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inneres Refugium", description = "{name}, Eure Weisheit und Führungsqualitäten sind eine Inspiration für uns alle!\n\nDer Orden des Verheerten Tempels möchte Euch eine komplette Rüstung für den Kampf gegen die Brennende Legion zur Verfügung stellen. Erweitert Euren Einfluss auf den Rest der Verheerten Inseln, dann ist der Sieg eines Tages unser.", sourceObjective = "Nehmt ein Geschenk vom Orden des Verheerten Tempels an.", completion = "In diesem Kampf ist unser Geist eins mit dem Euren, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[44250] = { id = 44250, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Champion des Lichts", description = "{name}, Eure Kraft und Führungsqualitäten sind eine Inspiration für uns alle!\n\nDie Silberne Hand möchte Euch eine komplette Rüstung für den Kampf gegen die Brennende Legion zur Verfügung stellen. Erweitert Euren Einfluss auf den Rest der Verheerten Inseln, dann ist der Sieg eines Tages unser.", sourceObjective = "Nehmt ein Geschenk der Silbernen Hand an.", completion = "Wir stehen Euch zur Seite, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[44251] = { id = 44251, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Machtwort: Rüstung", description = "{name}, Eure Weisheit und Führungsqualitäten sind eine Inspiration für uns alle!\n\nDie Konklave möchte Euch eine komplette Rüstung für den Kampf gegen die Brennende Legion zur Verfügung stellen. Erweitert Euren Einfluss auf den Rest der Verheerten Inseln, dann ist der Sieg eines Tages unser.", sourceObjective = "Nehmt ein Geschenk der Konklave an.", completion = "Wir stehen an Eurer Seite, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[44252] = { id = 44252, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für jede Klinge eine Scheide", description = "{name}, Eure Gerissenheit und Führungsqualitäten sind eine Inspiration für uns alle!\n\nDie Ungekrönten möchten Euch eine komplette Rüstung für den Kampf gegen die Brennende Legion zur Verfügung stellen. Erweitert Euren Einfluss auf den Rest der Verheerten Inseln, dann ist der Sieg eines Tages unser.", sourceObjective = "Nehmt ein Geschenk der Ungekrönten an.", completion = "Unsere Klingen gehören Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[44253] = { id = 44253, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Vision des Triumphs", description = "{name}, Eure Kraft und Führungsqualitäten sind eine Inspiration für uns alle!\n\nDer Irdene Ring möchte Euch eine komplette Rüstung für den Kampf gegen die Brennende Legion zur Verfügung stellen. Erweitert Euren Einfluss auf den Rest der Verheerten Inseln, dann ist der Sieg eines Tages unser.", sourceObjective = "Nehmt ein Geschenk vom Irdenen Ring an.", completion = "Wir stehen Euch zur Seite, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[44254] = { id = 44254, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Blick in das Vergessen", description = "{name}, Eure Weisheit und Führungsqualitäten sind eine Inspiration für uns alle!\n\nDer Rat der Schwarzen Ernte möchte Euch eine komplette Rüstung für den Kampf gegen die Brennende Legion zur Verfügung stellen. Erweitert Euren Einfluss auf den Rest der Verheerten Inseln, dann ist der Sieg eines Tages unser.", sourceObjective = "Nehmt ein Geschenk vom Rat der Schwarzen Ernte an.", completion = "Der Rat bewundert Eure Macht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[44255] = { id = 44255, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Axt im Haus", description = "{name}, Eure Kraft und Führungsqualitäten sind eine Inspiration für uns alle!\n\nDie Valarjar möchten Euch eine komplette Rüstung für den Kampf gegen die Brennende Legion zur Verfügung stellen. Erweitert Euren Einfluss auf den Rest der Verheerten Inseln, dann ist der Sieg eines Tages unser.", sourceObjective = "Nehmt ein Geschenk der Valarjar an.", completion = "Die Macht der Valarjar steht Euch zur Seite, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[44257] = { id = 44257, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Sternschnuppe", description = "<Khadgar überdenkt die Informationen, die Ihr ihm gebracht habt.>\n\nIhr sagt, es hätte eine Schneise durch den Teufelssturm geschlagen und so viel Macht ausgestrahlt, dass Euer Späher sie im ganzen Körper spüren konnte?\n\nEtwas so Mächtiges könnte sich als wirkungsvolle Waffe gegen die Brennende Legion erweisen!\n\nIch werde die anderen Ordensanführer über Eure Entdeckung informieren. Geht Ihr der Sache weiter auf den Grund! Ein Greif erwartet Euch bereits an Krasus' Landeplatz! Möge das Licht Euch leiten.", sourceObjective = "Findet das mysteriöse lichtgebundene Objekt.", progress = "Zeigt mir, was Ihr gefunden habt.", completion = "Äußerst merkwürdig, in der Tat! Dieses Objekt hat auf keinen Fall die Legion gefertigt. Das muss ich mir näher ansehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44258] = { id = 44258, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturm auf die Violette Festung: In die Violette Festung", description = "In der Violetten Festung befinden sich einige der mächtigsten Diener des Lichkönigs und sie könnte jeden Augenblick von Agenten der Legion überrannt werden. Wir müssen uns dort hinbegeben und die Dämonen vernichten, bevor sie die Gefangenen befreien.", sourceObjective = "Bezwingt den Anführer des Sturms auf die Violette Festung.", completion = "Konntet Ihr die Violette Festung bewältigen?", sourceObjectiveStatus = "unverified-source-field" }
quests[44259] = { id = 44259, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturm auf die Violette Festung: In die Violette Festung", description = "In der Violetten Festung befinden sich einige der mächtigsten Diener des Lichkönigs und sie könnte jeden Augenblick von Agenten der Legion überrannt werden. Wir müssen uns dort hinbegeben und die Dämonen vernichten, bevor sie die Gefangenen befreien.", sourceObjective = "Bezwingt den Anführer des Sturms auf die Violette Festung.", progress = "Wie gestaltet sich die Violette Festung?", completion = "Konntet Ihr die Violette Festung bewältigen?", sourceObjectiveStatus = "unverified-source-field" }
quests[44260] = { id = 44260, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Verlies der Wächterinnen: Ins Verlies der Wächterinnen", description = "Im Verlies der Wächterinnen ist es schlimmer, als wir gedacht hatten. Die Gefangenen haben sich selbst zu Wärtern gemacht und das Verlies vollständig übernommen. Laut unseren Berichten könnte sich Cordana Teufelsang ebenfalls dort aufhalten.\n\nBegebt Euch zum Verlies der Wächterinnen und läutert den Ort von allem Bösen.", sourceObjective = "Bezwingt Cordana Teufelsang im Verlies der Wächterinnen.", completion = "Konntet Ihr das Verlies der Wächterinnen bewältigen?", sourceObjectiveStatus = "unverified-source-field" }
quests[44261] = { id = 44261, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Verlies der Wächterinnen: Ins Verlies der Wächterinnen", description = "Im Verlies der Wächterinnen ist es schlimmer, als wir gedacht hatten. Die Gefangenen haben sich selbst zu Wärtern gemacht und das Verlies vollständig übernommen. Laut unseren Berichten könnte sich Cordana Teufelsang ebenfalls dort aufhalten.\n\nBegebt Euch zum Verlies der Wächterinnen und läutert den Ort von allem Bösen.", sourceObjective = "Bezwingt Cordana Teufelsang im Verlies der Wächterinnen.", progress = "Wie gestaltet sich das Verlies der Wächterinnen?", completion = "Konntet Ihr das Verlies der Wächterinnen bewältigen?", sourceObjectiveStatus = "unverified-source-field" }
quests[44262] = { id = 44262, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Arkus: In den Arkus", description = "Der Arkus ist viel größer, als wir gedacht hatten, und birgt viele Gefahren. Wenn wir überhaupt eine Chance haben wollen, die Stadt einzunehmen, müssen wir uns zuerst um den Untergrund kümmern.\n\nBetretet den Arkus und vernichtet sämtliche Feinde.", sourceObjective = "Bezwingt Berater Vandros im Arkus.", sourceObjectiveStatus = "unverified-source-field" }
quests[44263] = { id = 44263, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Arkus: In den Arkus", description = "Der Arkus ist viel größer, als wir gedacht hatten, und birgt viele Gefahren. Wenn wir überhaupt eine Chance haben wollen, die Stadt einzunehmen, müssen wir uns zuerst um den Untergrund kümmern.\n\nBetretet den Arkus und vernichtet sämtliche Feinde.", sourceObjective = "Bezwingt Berater Vandros im Arkus.", progress = "Wie gestaltet sich der Arkus?", completion = "Konntet Ihr den Arkus bewältigen?", sourceObjectiveStatus = "unverified-source-field" }
quests[44264] = { id = 44264, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharions Hort: In den Hort", description = "Laut unseren Spähern haben die Drogbar nicht nur ein Titanenrelikt gefunden, sondern auch eine Armee aufgestellt, die groß genug ist, um eine Bedrohung für die gesamte Oberwelt darzustellen.\n\nBegebt Euch in den Untergrund und haltet den Unterkönig auf, bevor er seine Drogbararmee in Marsch setzt.", sourceObjective = "Bezwingt Dargrul in Neltharions Hort.", completion = "Konntet Ihr Neltharions Hort bewältigen?", sourceObjectiveStatus = "unverified-source-field" }
quests[44265] = { id = 44265, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neltharions Hort: In den Hort", description = "Laut unseren Spähern haben die Drogbar nicht nur ein Titanenrelikt gefunden, sondern auch eine Armee aufgestellt, die groß genug ist, um eine Bedrohung für die gesamte Oberwelt darzustellen.\n\nBegebt Euch in den Untergrund und haltet den Unterkönig auf, bevor er seine Drogbararmee in Marsch setzt.", sourceObjective = "Bezwingt Dargrul in Neltharions Hort.", progress = "Wie gestalten sich die Herausforderungen in Neltharions Hort?", completion = "Konntet Ihr Neltharions Hort bewältigen?", sourceObjectiveStatus = "unverified-source-field" }
quests[44266] = { id = 44266, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Seelenschlund: In den Seelenschlund", description = "Unsere Späher berichten, dass verdammte Vrykul gezwungen werden, als Gefangene auf der Naglfar zu segeln, einem Schiff des Todes.\n\nBegebt Euch zum Seelenschlund und stellt Helya, bevor ihr noch mehr arme, unglückselige Seelen zum Opfer fallen.", sourceObjective = "Bezwingt Helya im Seelenschlund.", completion = "Konntet Ihr den Seelenschlund bewältigen?", sourceObjectiveStatus = "unverified-source-field" }
quests[44267] = { id = 44267, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Seelenschlund: In den Seelenschlund", description = "Unsere Späher berichten, dass verdammte Vrykul gezwungen werden, als Gefangene auf der Naglfar zu segeln, einem Schiff des Todes.\n\nBegebt Euch zum Seelenschlund und stellt Helya, bevor ihr noch mehr arme, unglückselige Seelen zum Opfer fallen.", sourceObjective = "Bezwingt Helya im Seelenschlund.", progress = "Wie gestalten sich die Herausforderungen im Seelenschlund?", completion = "Konntet Ihr den Seelenschlund bewältigen?", sourceObjectiveStatus = "unverified-source-field" }
quests[44268] = { id = 44268, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallen der Tapferkeit: Odyns Herausforderung", description = "Odyn selbst hat eine Nachricht geschickt. Er und seine Krieger warten in den Hallen der Tapferkeit auf würdige Anwärter.\n\nBezwingt die Champions in den Hallen der Tapferkeit und der Ruhm ist Euer.", sourceObjective = "Bezwingt Odyn in den Hallen der Tapferkeit.", completion = "Konntet Ihr Odyns Herausforderung bewältigen?", sourceObjectiveStatus = "unverified-source-field" }
quests[44269] = { id = 44269, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hallen der Tapferkeit: Odyns Herausforderung", description = "Odyn selbst hat eine Nachricht geschickt. Er und seine Krieger warten in den Hallen der Tapferkeit auf würdige Anwärter.\n\nBezwingt die Champions in den Hallen der Tapferkeit und der Ruhm ist Euer.", sourceObjective = "Bezwingt Odyn in den Hallen der Tapferkeit.", progress = "Wie gestalten sich die Hallen der Tapferkeit?", completion = "Konntet Ihr Odyns Herausforderung bewältigen?", sourceObjectiveStatus = "unverified-source-field" }
quests[44270] = { id = 44270, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge Azsharas: In das Auge Azsharas", description = "Unsere Untersuchung hat ergeben, dass die Naga auf persönlichen Befehl von Königin Azshara ein mächtiges Wesen beschwören wollen, das Azsharas Macht auf die Verheerten Inseln entfesseln wird.\n\nBegebt Euch zum Auge Azsharas und haltet das Ritual auf.", sourceObjective = "Bezwingt Azsharas Zorn im Auge Azsharas.", completion = "Konntet Ihr das Auge Azsharas bewältigen?", sourceObjectiveStatus = "unverified-source-field" }
quests[44271] = { id = 44271, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge Azsharas: In das Auge Azsharas", description = "Unsere Untersuchung hat ergeben, dass die Naga auf persönlichen Befehl von Königin Azshara ein mächtiges Wesen beschwören wollen, das Azsharas Macht auf die Verheerten Inseln entfesseln wird.\n\nBegebt Euch zum Auge Azsharas und haltet das Ritual auf.", sourceObjective = "Bezwingt Azsharas Zorn im Auge Azsharas.", progress = "Wie gestaltet sich das Auge Azsharas?", completion = "Konntet Ihr das Auge Azsharas bewältigen?", sourceObjectiveStatus = "unverified-source-field" }
quests[44272] = { id = 44272, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Finsterherzdickicht: Ins Finsterherzdickicht", description = "Im Schatten von Shaladrassil vergrößert Xavius seinen Einfluss, um den ehemals reinen Hain der Druiden zu unterjochen und zu verderben.\n\nAber das ist noch nicht alles. Xavius hat sich eine Trophäe aus den Reihen der Druiden geholt und wird seine Rache langsam und grausam genießen. Wir sollten zum Finsterherzdickicht aufbrechen und seine teuflischen Pläne vereiteln.", sourceObjective = "Bezwingt den Schemen von Xavius im Finsterherzdickicht.", completion = "Konntet Ihr das Finsterherzdickicht bewältigen?", sourceObjectiveStatus = "unverified-source-field" }
quests[44273] = { id = 44273, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Finsterherzdickicht: Ins Finsterherzdickicht", description = "Im Schatten von Shaladrassil vergrößert Xavius seinen Einfluss, um den ehemals reinen Hain der Druiden zu unterjochen und zu verderben.\n\nAber das ist noch nicht alles. Xavius hat sich eine Trophäe aus den Reihen der Druiden geholt und wird seine Rache langsam und grausam genießen. Wir sollten zum Finsterherzdickicht aufbrechen und seine teuflischen Pläne vereiteln.", sourceObjective = "Bezwingt den Schemen von Xavius im Finsterherzdickicht.", progress = "Wie gestaltet sich das Finsterherzdickicht?", completion = "Konntet Ihr das Finsterherzdickicht bewältigen?", sourceObjectiveStatus = "unverified-source-field" }
quests[44274] = { id = 44274, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hof der Sterne: In den Hof der Sterne", description = "Das Wetter ist einfach perfekt für ein Fest, nicht wahr?\n\nBegebt Euch zum Hof der Sterne. Dort könnt Ihr vielleicht die Großmagistrix persönlich dabei erblicken, wie sie all die Adeligen von der Notwendigkeit der vielen Legionspatrouillen überzeugt.", sourceObjective = "Bezwingt Berater Melandrus am Hof der Sterne.", sourceObjectiveStatus = "unverified-source-field" }
quests[44275] = { id = 44275, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Hof der Sterne: In den Hof der Sterne", description = "Das Wetter ist einfach perfekt für ein Fest, nicht wahr?\n\nBegebt Euch zum Hof der Sterne. Dort könnt Ihr vielleicht die Großmagistrix persönlich dabei erblicken, wie sie all die Adeligen von der Notwendigkeit der vielen Legionspatrouillen überzeugt.", sourceObjective = "Bezwingt Berater Melandrus am Hof der Sterne.", progress = "Wie gestaltet sich der Hof der Sterne?", completion = "Konntet Ihr die Herausforderung bewältigen?", sourceObjectiveStatus = "unverified-source-field" }
quests[44276] = { id = 44276, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rabenwehr: Der Herr der Rabenwehr", description = "Während unsere Champions die Überreste der Rabenwehr untersuchten, gerieten sie in einen Hinterhalt! Der Herr der Rabenwehr hat sich offenbar mit der Legion zusammengetan.\n\nWir brauchen Eure Hilfe, um seine immer größer werdende Armee zu besiegen und ihn zur Strecke zu bringen.", sourceObjective = "Bezwingt Lord Kur'talos Rabenkrone in der Rabenwehr.", completion = "Habt Ihr Lord Rabenkrone bezwingen können?", sourceObjectiveStatus = "unverified-source-field" }
quests[44277] = { id = 44277, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rabenwehr: Der Herr der Rabenwehr", description = "Während unsere Champions die Überreste der Rabenwehr untersuchten, gerieten sie in einen Hinterhalt! Der Herr der Rabenwehr hat sich offenbar mit der Legion zusammengetan.\n\nWir brauchen Eure Hilfe, um seine immer größer werdende Armee zu besiegen und ihn zur Strecke zu bringen.", sourceObjective = "Bezwingt Lord Kur'talos Rabenkrone in der Rabenwehr.", progress = "Seid Ihr schon in der Rabenwehr gewesen?", completion = "Habt Ihr Lord Rabenkrone bezwingen können?", sourceObjectiveStatus = "unverified-source-field" }
quests[44278] = { id = 44278, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Freiheit für die Illidari", description = "<Arduen Seelenklinge blutet aus mehreren grässlichen Wunden. Offensichtlich ist er hier zum Sterben zurückgelassen worden.>\n\nIm Gefängnis sind noch drei unserer... <hust>... Kameraden.\n\nWir sind auf unserer Patrouille hier in einen Hinterhalt geraten.\n\nFür mich besteht keine Hoffnung mehr, {name}, aber bitte... Ihr könnt die anderen immer noch retten.", sourceObjective = "Befreit Sirius Schwarzschwinge, Cassiel Nachtdorn und Asha Rabenruf.", completion = "Über den Verlust von Arduen, Cassiel und Sirius trauern wir zusammen, Bruder. Aber ich verdanke Euch mein Leben... wieder einmal.\n\nEins habe ich während meiner Zeit im Gefängnis gelernt: Die Dämonen in der Rabenwehr müssen sterben.", sourceObjectiveStatus = "unverified-source-field" }
quests[44279] = { id = 44279, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Highmountain - Treasure 0xx - Bloodhunt Highland - S (RKS)" }
quests[44280] = { id = 44280, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "7.0 Highmountain - Treasure 0x2 - Bloodhunt Highland - S (RKS)" }
quests[44281] = { id = 44281, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Allzeit bereit", description = "Unsere Verbündeten haben die Reise nach Orgrimmar auf sich genommen, um unsere Kriegsanstrengungen zu unterstützen.\n\nNehmt Euch die Zeit und sucht sie auf, {name}. Ihr Beistand wird uns heute zum Sieg verhelfen.", sourceObjective = "Besucht die Streitkräfte der Horde an der Blockade von Dranosh'ar.", completion = "Ihr scheint auf einen Kampf vorbereitet zu sein. Lasst Euch da draußen nicht vom Blutrausch überwältigen.\n\nDer Kriegshäuptling möchte Euch diesen Ring schenken, bevor Ihr in den Kampf zieht. Mögt Ihr mit den Köpfen vieler Dämonen zurückkehren.", sourceObjectiveStatus = "unverified-source-field" }
quests[44282] = { id = 44282, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Auge Azsharas: Die gefrorene Seele", description = "Ah, <Todesgebieter/Todesgebieterin>. Schön, Euch zu sehen. Ich hätte da eine faszinierende Aufgabe für Euch, falls Ihr in der Stimmung für Abenteuer seid.\n\nVor Kurzem bin ich über einen merkwürdigen Verweis auf ein uraltes Amulett gestolpert, das Königin Azshara höchstpersönlich geschaffen hat! Man nennt es den Eisseelenanhänger und es verleiht demjenigen, der die Kraft des Eises kanalisieren kann, ungeheure Macht.\n\nIch habe Grund zu der Annahme, dass es sich irgendwo im Auge Azsharas befindet.\n\nBeschafft mir den Anhänger und er wird sich bei meinen Studien als äußerst nützlich erweisen.", sourceObjective = "Beschafft den Eisseelenanhänger von Azsharas Zorn.", progress = "Habt Ihr den Anhänger besorgt?", completion = "Also das ist der legendäre Eisseelenanhänger! Ich spüre große Kraft in diesem Gegenstand...\n\nIch werde umgehend damit beginnen, ihn zu untersuchen. Ich bin Euch dankbar, Todesgebieter.", sourceObjectiveStatus = "unverified-source-field" }
quests[44283] = { id = 44283, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Smaragdgrüne Alptraum: Den Schleier lüften", description = "Die Finsternis des Alptraums ist wie ein schwerer Vorhang, der die Wirklichkeit verzerrt und die Wahrnehmung aller lebenden Wesen verändert. Wenn Teile des Traums gesäubert werden, lässt Xavius' Macht nach und der Weg zum Herzen des Alptraums wird aufgedeckt. Doch es gibt vielleicht noch einen direkteren Weg... Mein Lehrer sprach einst von einer reinen Kraft, die die Dunkelheit des Alptraums erhellen kann, damit alle Wege klar vor einem liegen. Doch leider weilt Cenarius nicht mehr unter uns...", sourceObjective = "Sammelt 4 Essenzen der Klarheit von Cenarius im Smaragdgrünen Alptraum auf dem Schwierigkeitsgrad 'Normal'.", progress = "Wenn Cenarius doch nur noch unter uns weilen würde... Dann könnten wir Xavius sofort konfrontieren.", completion = "Unglaublich... Wo habt Ihr die gefunden? Mit diesen Essenzen kann ich einen Weg direkt ins Herz des Alptraums öffnen. Wir sollten uns beeilen!", sourceObjectiveStatus = "unverified-source-field" }
quests[44284] = { id = 44284, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Smaragdgrüne Alptraum: Den Schleier lüften", description = "Die Finsternis des Alptraums ist wie ein schwerer Vorhang, der die Wirklichkeit verzerrt und die Wahrnehmung aller lebenden Wesen verändert. Wenn Teile des Traums gesäubert werden, lässt Xavius' Macht nach und der Weg zum Herzen des Alptraums wird aufgedeckt. Doch es gibt vielleicht noch einen direkteren Weg... Mein Lehrer sprach einst von einer reinen Kraft, die die Dunkelheit des Alptraums erhellen kann, damit alle Wege klar vor einem liegen. Doch leider weilt Cenarius nicht mehr unter uns...", sourceObjective = "Sammelt 4 Essenzen der Klarheit von Cenarius im Smaragdgrünen Alptraum auf dem Schwierigkeitsgrad 'Heroisch'.", progress = "Wenn Cenarius doch nur noch unter uns weilen würde... Dann könnten wir Xavius sofort konfrontieren.", completion = "Unglaublich... Wo habt Ihr die gefunden? Mit diesen Essenzen kann ich einen Weg direkt ins Herz des Alptraums öffnen. Wir sollten uns beeilen!", sourceObjectiveStatus = "unverified-source-field" }
quests[44285] = { id = 44285, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Smaragdgrüne Alptraum: Den Schleier lüften", description = "Die Finsternis des Alptraums ist wie ein schwerer Vorhang, der die Wirklichkeit verzerrt und die Wahrnehmung aller lebenden Wesen verändert. Wenn Teile des Traums gesäubert werden, lässt Xavius' Macht nach und der Weg zum Herzen des Alptraums wird aufgedeckt. Doch es gibt vielleicht noch einen direkteren Weg... Mein Lehrer sprach einst von einer reinen Kraft, die die Dunkelheit des Alptraums erhellen kann, damit alle Wege klar vor einem liegen. Doch leider weilt Cenarius nicht mehr unter uns...", sourceObjective = "Sammelt 4 Essenzen der Klarheit von Cenarius im Smaragdgrünen Alptraum auf dem Schwierigkeitsgrad 'Mythisch'.", progress = "Wenn Cenarius doch nur noch unter uns weilen würde... Dann könnten wir Xavius sofort konfrontieren.", completion = "Unglaublich... Wo habt Ihr die gefunden? Mit diesen Essenzen kann ich einen Weg direkt ins Herz des Alptraums öffnen. Wir sollten uns beeilen!", sourceObjectiveStatus = "unverified-source-field" }
quests[44286] = { id = 44286, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Verlies der Wächterinnen: Ein fleischiges Meisterstück", description = "Ah, <Todesgebieter/Todesgebieterin>! Welch angenehme Überraschung! Ihr besucht meine Werkstatt für Blut und Fleisch nicht sehr oft.\n\nUm genau zu sein, habe ich etwas ganz Besonderes, das ich Euch zeigen möchte. Ich habe eine neue Monstrosität entwickelt, bei der sich menschliches Fleisch mit dem von Dämonen vermischt.\n\nMein erster Prototyp, Moderdarm, ist fast fertig! Mir fehlen allerdings einige der Körperteile, an die man nicht so einfach herankommt.\n\nDie Gefangenen im Verlies der Wächterinnen dürften hervorragende Spender für die von mir benötigten Körperteile abgeben.", sourceObjective = "Beschafft das schlagende Teufelsherz und dämonische Eingeweide aus dem Verlies der Wächterinnen.", progress = "Habt Ihr die Körperteile beschafft?", completion = "Ja, diese Teile werden ihren Zweck erfüllen!\n\nJetzt geht und stellt Euch Moderdarm vor! Ich bin sicher, bei Euch beiden werden die Fetzen fliegen!", sourceObjectiveStatus = "unverified-source-field" }
