quests[44306] = { id = 44306, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Segen des Ordens", description = "Obwohl es Zeit und Mittel benötigt, sind wir selbstverständlich in der Lage, Eure Champions zu segnen. Mit diesem Segen werden ihre Abenteuer weitaus erfolgreicher verlaufen.", sourceObjective = "Erbittet einen Segen des Ordens.", completion = "Die Segnungen sind unterwegs, Ihr werdet sie hier bald in Empfang nehmen können.", sourceObjectiveStatus = "unverified-source-field" }
