quests[44310] = { id = 44310, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreifache Macht", description = "Wir haben Informationen über das letzte Artefakt, nach dem Ihr vielleicht suchen solltet, wenn Ihr vorhabt, noch andere Magiearten anzuwenden.\n\nHier sind alle Einzelheiten. Lasst mich wissen, wie Ihr vorgehen wollt.", sourceObjective = "Sagt Meryl Bescheid, wenn Ihr einem weiteren Artefakt nachgehen wollt.", completion = "So soll es geschehen.", sourceObjectiveStatus = "unverified-source-field" }
