quests[44336] = { id = 44336, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: The Missing Vessel 4" }
quests[44337] = { id = 44337, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Göttin wache über Euch", description = "Ich habe womöglich einen \"Schlüssel\" gefunden, um das Herz des Lichts aufzuschließen, {name}.\n\nIch blätterte durch einige uralte kosmologische Folianten, als ich über eine Passage stolperte, die besagte, dass der höchste Naaru möglicherweise während der großen Ordnung von Licht und Schatten von Elune selbst geschaffen wurde.\n\nWenn Elune Xe'ra tatsächlich erschaffen hat, dann würde es einleuchten, dass wir mit den Tränen von Elune die Geheimnisse des Herzens des Lichts erschließen können.\n\nEs ist zwar weit hergeholt, aber wir haben nichts mehr zu verlieren.\n\nTrefft mich in Dalaran. Ich werde die Tränen von Elune für Euch vorbereiten.", sourceObjective = "Trefft Erzmagier Khadgar in Dalaran.", completion = "Wenn das funktioniert, besteht vielleicht ja doch noch Hoffnung für Turalyon und die Armee des Lichts.", sourceObjectiveStatus = "unverified-source-field" }
quests[44338] = { id = 44338, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Göttin wache über Euch", description = "Ich habe womöglich einen \"Schlüssel\" gefunden, um das Herz des Lichts aufzuschließen, {name}.\n\nIch blätterte durch einige uralte kosmologische Folianten, als ich über eine Passage stolperte, die besagte, dass der höchste Naaru möglicherweise während der großen Ordnung von Licht und Schatten von Elune selbst geschaffen wurde.\n\nWenn Elune Xe'ra tatsächlich erschaffen hat, dann würde es einleuchten, dass wir mit den Tränen von Elune die Geheimnisse des Herzens des Lichts erschließen können.\n\nJetzt liegt es an Euch, die Tränen von Elune aus Val'sharah zu beschaffen.", sourceObjective = "Bergt die Tränen von Elune aus Val'sharah.", completion = "Wenn das funktioniert, besteht vielleicht ja doch noch Hoffnung für Turalyon und die Armee des Lichts.", sourceObjectiveStatus = "unverified-source-field" }
