quests[44366] = { id = 44366, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein letztes Abenteuer", description = "Es gibt noch einen letzten Weg, den Ihr vielleicht gehen solltet... noch eine Waffe, die Ihr vielleicht führen solltet.\n\nWenn Ihr diese suchen wollt, müsst Ihr nur Bescheid geben.", sourceObjective = "Sagt Emmarel Bescheid, wenn Ihr einem weiteren Artefakt nachgehen wollt.", completion = "So soll es sein.", sourceObjectiveStatus = "unverified-source-field" }
