quests[44370] = { id = 44370, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Euer Arsenal vervollständigen", description = "Hochlord, da draußen ist immer noch eine letzte Waffe, die Euch im Kampf gegen die Legion helfen würde.\n\nWenn es Euch recht ist, würde ich gerne mit Euch unsere neuesten Informationen darüber durchgehen, wo sie sich befinden könnte.", sourceObjective = "Sagt Tyrosus Bescheid, wenn Ihr einem weiteren Artefakt nachgehen wollt.", completion = "Einverstanden. Wir müssen sie sofort suchen.", sourceObjectiveStatus = "unverified-source-field" }
