quests[44375] = { id = 44375, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzte Klinge", description = "Wie Ihr Euch sicherlich erinnert, haben wir den letzten Satz unserer Pläne zurückgehalten, eine Waffe unglaublicher Macht zu beschaffen.\n\nIhr will Euch natürlich nicht unter Druck setzen, aber wenn Ihr dieser Waffe nachgehen wollt, sagt mir einfach Bescheid.", sourceObjective = "Sagt Jorach Bescheid, wenn Ihr einem weiteren Artefakt nachgehen wollt.", completion = "Ganz meine Meinung.", sourceObjectiveStatus = "unverified-source-field" }
quests[44376] = { id = 44376, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Assassination Chosen" }
quests[44377] = { id = 44377, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Combat Chosen" }
quests[44378] = { id = 44378, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Subtlety Chosen" }
quests[44379] = { id = 44379, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Jagd nach Macht", description = "Es gibt noch ein Paar Klingen in erreichbarer Nähe, die Euch im Kampf gegen die Legion helfen würden.\n\nWenn Ihr ihnen nachgehen wollt, sagt mir einfach Bescheid.", sourceObjective = "Sagt Altruis Bescheid, wenn Ihr einem weiteren Artefakt nachgehen wollt.", completion = "Gute Idee. Es gibt keinen verlässlicheren Verbündeten als eine würdige Klinge.", sourceObjectiveStatus = "unverified-source-field" }
quests[44380] = { id = 44380, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Havoc Chosen" }
