quests[44382] = { id = 44382, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance Chosen" }
quests[44383] = { id = 44383, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Jagd nach Macht", description = "Es gibt immer noch ein Paar Klingen, die Euch bei den bevorstehenden Kämpfen von großem Nutzen sein könnten.\n\nIch kann Euch darüber ins Bild setzen, was wir wissen, wenn Ihr ihnen nachgehen wollt.", sourceObjective = "Sagt Kayn Bescheid, wenn Ihr einem weiteren Artefakt nachgehen wollt.", completion = "Das halte ich für weise. Wir brauchen jede Waffe, derer wir habhaft werden können, um die Legion ein für alle Mal zu vernichten.", sourceObjectiveStatus = "unverified-source-field" }
