quests[44399] = { id = 44399, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Thunderaan's Enemies 4" }
quests[44400] = { id = 44400, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturm auf die Violette Festung: Fiasko in der Festung", description = "Schon wieder! Es ist schon wieder geschehen!\n\nNatürlich steckt die Legion dieses Mal hinter dem Gefängnisausbruch, aber ich habe ja allen im Vorfeld schon gesagt, dass es keine gute Idee ist, einige der gefährlichsten Wesen Azeroths in einem Gefängnis mitten in unserer Stadt unterzubringen!\n\nIch nehme an, wir können uns später noch über eine Verlegung unterhalten. Jetzt müssen wir uns erst einmal um ein wenig... Befriedung kümmern.\n\nKönnt Ihr helfen?", sourceObjective = "Schlagt den Sturm auf die Violette Festung zurück.", progress = "Oh nein. Sagt mir nicht, dass NOCH ETWAS schiefgegangen ist!?", completion = "Puh. Das ist schon die ZWEITE abgewehrte Invasion. Gut gemacht.\n\nUnd mit wem muss ich jetzt reden, damit hier alles dichtgemacht wird?", sourceObjectiveStatus = "unverified-source-field" }
quests[44401] = { id = 44401, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Waffe für jede Gelegenheit", description = "Unser Verbündeter, der Lichkönig, hat angeboten, Euch einen Hinweis auf eine letzte Waffe zukommen zu lassen, wenn Ihr Eure Offensivoptionen maximieren wollt.\n\nSagt mir Bescheid, wie Ihr weiter vorgehen wollt.", sourceObjective = "Sagt Herzog Lankral Bescheid, wenn Ihr einem weiteren Artefakt nachgehen wollt.", completion = "Nun gut.", sourceObjectiveStatus = "unverified-source-field" }
quests[44402] = { id = 44402, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood Chosen" }
