quests[44404] = { id = 44404, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unholy Chosen" }
quests[44405] = { id = 44405, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Azsuna - Treasure 047 - Smuggler's Camp" }
quests[44406] = { id = 44406, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aggras Anleitung", description = "{class}t, habt Ihr schon die Schamanin Aggra kennengelernt? Sie entstammt einer zerschmetterten Welt und lernte von den Mag'harorcs der Scherbenwelt alles über die Gesetze der Elemente. Am Vorabend des Kataklysmus nahm sie es auf sich, Thralls Schamanenausbildung abzuschließen. Unsere jüngeren Initianden haben großes Glück, dass sie unter uns weilt, um sie anzuleiten.\n\nWenn Ihr noch ein zweites Artefakt suchen wollt, kann Aggra Euch helfen. Sie bildet neue Rekruten über uns in der Sturmaugenwarte aus.", sourceObjective = "Sucht Aggra in der Sturmaugenwarte im Herz von Azeroth auf.", completion = "Ich habe auf Euch gewartet, Scharfseher.", sourceObjectiveStatus = "unverified-source-field" }
quests[44407] = { id = 44407, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die dritte Legende", description = "Ihr habt nicht nur eines, sondern gleich ZWEI mächtige Artefakte, die Ihr gegen die Legion einsetzen könnt. Aber könnt Ihr Euch vorstellen, wie die Welt aussähe, wenn Ihr drei hättet? Denkt doch, was Ihr in einer solchen Welt alles tun könntet!\n\nSollen wir uns die Möglichkeiten einmal ansehen?", sourceObjective = "Sprecht mit Alonsus Faol, um einem dritten Artefakt nachzugehen.", completion = "Das war wahrscheinlich die leichteste Entscheidung, die Ihr je fällen musstet! Fangen wir an.", sourceObjectiveStatus = "unverified-source-field" }
quests[44408] = { id = 44408, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadow Chosen" }
quests[44409] = { id = 44409, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disc Chosen" }
quests[44410] = { id = 44410, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holy Chosen" }
quests[44411] = { id = 44411, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Merkwürdig summender Kristall", description = "<Ihr legt den Kristall an Euer Ohr und hört das unharmonische Stimmengewirr von Hunderten Stimmen, die gleichzeitig sprechen. Vielleicht weiß Khadgar mehr über diesen merkwürdigen Edelstein.>", sourceObjective = "Bringt den merkwürdig summenden Kristall zu Khadgar in Dalaran.", completion = "Welch eine Kakophonie! Ich hörte sie bereits, bevor Ihr ihn aus Eurem Rucksack gezogen habt.\n\nIhr habt dort einen Speicherkristall der Hochgeborenen, der noch halbwegs intakt ist. Diese Kristalle wurden durch uralte Zauberei geschaffen, um Erinnerungen, Erzählungen, Musik, Geschichte und alles Mögliche zu speichern.\n\nDie sind sehr selten! Wenn ich daran etwas herumbastele, sollte ich etwas Nützliches daraus machen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[44412] = { id = 44412, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überall Gegner", description = "Moment mal, {name}. Während ich Eure Kugel untersuche, könnt Ihr doch etwas für mich untersuchen, oder?\n\nIch vermute schon seit Langem, dass Dalaran infiltriert wird. Aber nach einer peinlichen Begegnung mit der örtlichen Floristin will ich lieber sichergehen, dass meine These stimmt.\n\nHabt Ihr bemerkt, dass es einige Bürger gibt, die etwas zu weltlich aussehen? Beinahe unmenschlich? Spione, die finsteren Meistern dienen, sind unter uns und warten nur darauf, dass wir ihnen den Rücken kehren. Merzt sie aus, aber versucht das ohne viel Aufhebens zu tun.", sourceObjective = "Vernichtet die geheimen Infiltratoren in Dalaran.", progress = "Habt Ihr unsere Freunde schon aus dem Weg geschafft?", completion = "Danke für Eure Diskretion, {name}.\n\nSeht her, ich habe meine gesamte weltliche Weisheit sowie meine männlichen, markanten Gesichtszüge in diese Kugel übertragen. Ich bin sicher, Ihr werdet meinen Rat auf Euren Reisen nützlich finden.\n\nIch konnte ihr nur eine Handvoll Sätze beibringen, also müsst Ihr Eure Fragen SEHR GENAU stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44414] = { id = 44414, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsbrut von Lothros", description = "Diese Teufelsbrut nimmt einfach kein Ende! Ich kann sie nicht schnell genug niedermähen, um an den Schreckenslord im Mausoleum zu gelangen.\n\nMeister Illidan, werdet Ihr mich begleiten, damit wir Lothros gemeinsam zur Strecke bringen können?", sourceObjective = "Bezwingt Lothros.", progress = "Ein Schreckenslord ist keine große Bedrohung für Euch, oder?", completion = "Wir haben es geschafft! Aber ich fürchte, ohne Euch hätten wir diesen Ansturm nicht überstanden.", sourceObjectiveStatus = "unverified-source-field" }
quests[44415] = { id = 44415, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die rote Axt", description = "Broxigar der Rote ist auf der Brücke in Bedrängnis. Ich bin mir sicher, dass er uns niemals um Hilfe bitten würde, aber ich glaube, er könnte jetzt etwas Unterstützung vertragen.\n\nWenn Ihr entscheidet, unserem Verbündeten zur Hilfe zu eilen, würde ich Euch gern begleiten.", sourceObjective = "Schließt die instabilen Portale und macht Euch auf den Weg zu Broxigar dem Roten.", progress = "Unsere Verbündeten sind stark, aber unser Feind ist Legion!", completion = "Weise Krieger heißen alle Verbündeten willkommen. Ihr kämpft mit der Kraft eines Orcs.", sourceObjectiveStatus = "unverified-source-field" }
quests[44416] = { id = 44416, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jäger der Nacht", description = "Was für ein glorreicher Kampf!\n\nUnd wenn ich mich nicht täusche, wird es gleich noch etwas tödlicher.\n\nDie Legion setzt nämlich gern solches Schlachtvieh ein, um den Weg für größere Gegner frei zu machen.\n\nMeine Axt ist scharf und bereit.", sourceObjective = "Bezwingt Malvingeroth.", progress = "Seid Ihr Euch sicher, dass Ihr ein {race} seid? Ihr pflügt ja durch den Kampf wie ein Orc!", completion = "Die Geister ehren uns mit einem Tag voller glorreicher Kämpfe! Ich schulde Euch meinen Respekt, Illidan Sturmgrimm. Ich werde Euch gern in jede Schlacht folgen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44417] = { id = 44417, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch eine Legende", description = "Zwei sind gut, aber drei wären besser. Ihr solltet Eurem Arsenal noch ein Artefakt hinzufügen.\n\nWas meint Ihr?", sourceObjective = "Sprecht mit Odyn, um nach einem weiteren Artefakt zu suchen.", completion = "Damit werdet Ihr Eure Stärke noch einmal deutlich erhöhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44418] = { id = 44418, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fury Chosen" }
quests[44419] = { id = 44419, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arms Chosen" }
quests[44420] = { id = 44420, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prot Chosen" }
quests[44421] = { id = 44421, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anormale Anomalien", description = "Dalaran hierher zu bewegen, sollte nur eine vorübergehende Maßnahme sein, aber wir müssen vielleicht früher als erwartet weiterziehen.\n\nDas Teleportieren einer Stadt durch die Welt ist keine einfache Aufgabe. Die Menge der dafür erforderlichen Energien kann zu... unerwarteten Nebenwirkungen führen.\n\nDie Arkananomalien in der Stadt sorgen für Störungen. Allein das könnte den Erfolg einer weiteren Teleportation gefährden.\n\nWir können nicht warten, bis sie sich von selbst auflösen, {name}. Ich habe hier ein Gerät, mit dem Ihr diese Aufgabe etwas beschleunigen könnt.", sourceObjective = "Verwendet Khadgars Kristall, um die Anomalien in Dalaran zu neutralisieren.", completion = "Gute Arbeit. Es werden immer noch ein paar versprengte Anomalien vorhanden sein, aber durch Euren Eingriff sollten wir jetzt nicht mehr davon abgehalten werden, die Stadt zu bewegen.\n\nJetzt müssen wir nur noch das Ziel festlegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[44424] = { id = 44424, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drei Pfade, drei Waffen", description = "Wir haben geforscht und einen neuen Hinweis auf ein weiteres nützliches Artefakt gefunden.\n\nHier, lasst mich Euch zeigen, was ich gefunden habe. Wenn es Euch interessiert, dann lasst es mich einfach wissen.", sourceObjective = "Wählt ein drittes Artefakt, nach dem Ihr suchen wollt.", completion = "Eine weise Entscheidung.", sourceObjectiveStatus = "unverified-source-field" }
quests[44426] = { id = 44426, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talking Pair Flavor Heard" }
