quests[44431] = { id = 44431, flavor = "source-reference", locale = "deDE", source = "MultiLanguage retail a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceFlavor = "retail", sourceRevision = "a54af98d3013271c6f2cac8c5c00bbf4d74185bd", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch mehr alte Waffen", description = "Ihr habt große Erfolge gegen unsere Feinde errungen, aber Ihr solltet auf alles vorbereitet sein, was sie auf Euch loslassen.\n\nIhr wäret gut beraten, darüber nachzudenken, noch eine uralte Waffe zu besorgen, die uns in diesem Kampf weiterhelfen könnte.\n\nLasst mich wissen, wie Ihr verfahren wollt.", sourceObjective = "Wählt ein drittes Artefakt, nach dem Ihr suchen wollt.", completion = "Eine gute Wahl.", sourceObjectiveStatus = "unverified-source-field" }
